<?php require_once __DIR__.'/../includes/layout.php'; require_permission('certificates.manage'); if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); db()->prepare('UPDATE user_profiles SET certificate_number=?, msr_number=? WHERE user_id=?')->execute([$_POST['certificate_number'],$_POST['msr_number'],(int)$_POST['user_id']]); audit('certificate_update','users',(int)$_POST['user_id']);} $q='%'.($_GET['q']??'').'%'; $s=db()->prepare('SELECT p.*,u.username,u.email FROM user_profiles p JOIN users u ON u.id=p.user_id WHERE p.full_name LIKE ? OR u.username LIKE ? OR p.certificate_number LIKE ? OR p.msr_number LIKE ? ORDER BY p.created_at DESC LIMIT 200'); $s->execute([$q,$q,$q,$q]); dashboard_header('Manage Certificates'); ?><div class="glass-card p-4"><form class="mb-3"><input name="q" class="form-control" placeholder="Search certificates"></form><table class="table"><tr><th>User</th><th>Name</th><th>Certificate</th><th>MSR</th><th>Action</th></tr><?php foreach($s as $r):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="user_id" value="<?=$r['user_id']?>"><td><?=e($r['username'])?></td><td><?=e($r['full_name'])?></td><td><input name="certificate_number" value="<?=e($r['certificate_number'])?>" class="form-control"></td><td><input name="msr_number" value="<?=e($r['msr_number'])?>" class="form-control"></td><td><button class="btn btn-premium btn-sm">Save</button></td></form></tr><?php endforeach;?></table></div><?php dashboard_footer(); ?>
